  --tag-on-solid: var(--orange-foreground);
  --tag-subtle: var(--orange-subtle);
  --tag-text: var(--orange-text);
}

.amber {
  --tag-solid: var(--amber);
  --tag-on-solid: var(--amber-foreground);
  --tag-subtle: var(--amber-subtle);
  --tag-text: var(--amber-text);
