.violet {
  --tag-solid: var(--violet);
  --tag-on-solid: var(--violet-foreground);
  --tag-subtle: var(--violet-subtle);
  --tag-text: var(--violet-text);
}

.purple {
  --tag-solid: var(--purple);
  --tag-on-solid: var(--purple-foreground);
  --tag-subtle: var(--purple-subtle);
  --tag-text: var(--purple-text);
}

.fuchsia {
  --tag-solid: var(--fuchsia);
  --tag-on-solid: var(--fuchsia-foreground);
  --tag-subtle: var(--fuchsia-subtle);
  --tag-text: var(--fuchsia-text);
}

.pink {
  --tag-solid: var(--pink);
  --tag-on-solid: var(--pink-foreground);
  --tag-subtle: var(--pink-subtle);
  --tag-text: var(--pink-text);
}

.rose {
  --tag-solid: var(--rose);
  --tag-on-solid: var(--rose-foreground);
  --tag-subtle: var(--rose-subtle);
  --tag-text: var(--rose-text);
}

.subtle {
  background: var(--tag-subtle);
  color: var(--tag-text);
}

.outlined {
  border-color: var(--tag-text);
  color: var(--tag-text);
}

.solid {
  background: var(--tag-solid);
  color: var(--tag-on-solid);
}

.remove {
  position: relative;
  display: inline-flex;
  flex-shrink: 0;
  margin: 0;
  margin-inline-end: calc(var(--space-1) * -1);
  padding: 0;
  border: 0;
  border-radius: max(var(--radius-sm), var(--radius-full));
  background: transparent;
  color: inherit;
  font-size: var(--tag-icon);
  cursor: var(--cursor-button);
}

/* A tint of whatever colour the tag's text is, so hover reads on every
   variant and appearance without a token per combination. */
.remove:hover {
  background: color-mix(in oklch, currentColor 15%, transparent);
}

/* Same 2px ring as every control; the offset is 1px rather than 2px so the
   ring stays inside a 20px tag. */
.remove:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 1px;
}

/* The visible button is 16px; on touch screens the hit area grows to 44px
   without the tag growing with it. */
@media (pointer: coarse) {
  .remove::before {
    content: '';
    position: absolute;
    inset: 50% auto auto 50%;
    inline-size: 44px;
    block-size: 44px;
    translate: -50% -50%;
  }
}
